import React, { useRef, useState } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls, ContactShadows, PerspectiveCamera } from '@react-three/drei';
import * as THREE from 'three';

function Leaf({ spotPosition }) {
  const mesh = useRef();
  
  // Subtle "wind" animation to make it look cinematic
  useFrame((state) => {
    const t = state.clock.getElapsedTime();
    mesh.current.rotation.x = THREE.MathUtils.lerp(mesh.current.rotation.x, Math.cos(t / 2) / 10 + 0.25, 0.1);
    mesh.current.rotation.y = THREE.MathUtils.lerp(mesh.current.rotation.y, Math.sin(t / 4) / 10, 0.1);
  });

  return (
    <mesh ref={mesh} rotation={[0.5, 0, 0]} castShadow>
      {/* A simple curved leaf shape using a sphere segment or plane */}
      <sphereGeometry args={[2, 32, 32, 0, Math.PI / 2, 0, Math.PI / 2]} />
      <meshStandardMaterial 
        color="#2d6a4f" 
        side={THREE.DoubleSide} 
        roughness={0.4}
        metalness={0.1}
      />
      
      {/* The Leaf Spot: A small red/brown indicator */}
      {spotPosition && (
        <mesh position={spotPosition}>
          <sphereGeometry args={[0.08, 16, 16]} />
          <meshStandardMaterial color="#7f4f24" emissive="#3e2723" />
        </mesh>
      )}
    </mesh>
  );
}

export default function LeafCanvas() {
  const [spot, setSpot] = useState([0.5, 1.2, 0.8]); // Default spot location

  return (
    <div style={{ width: '100%', height: '400px', background: '#f0fdf4', borderRadius: '16px' }}>
      <Canvas shadows>
        <PerspectiveCamera makeDefault position={[0, 0, 5]} />
        <ambientLight intensity={0.5} />
        <pointLight position={[10, 10, 10]} intensity={1} castShadow />
        <spotLight position={[-10, 10, 10]} angle={0.15} penumbra={1} />
        
        <Leaf spotPosition={spot} />
        
        <OrbitControls enableZoom={false} />
        <ContactShadows position={[0, -2, 0]} opacity={0.4} scale={10} blur={2.5} far={4} />
      </Canvas>
      
      <p style={{ textAlign: 'center', fontSize: '12px', color: '#064e3b', marginTop: '-40px', position: 'relative' }}>
        🖱️ Rotate the leaf to inspect "Leaf Spots" [Fungicide: Apply at Brown Zones]
      </p>
    </div>
  );
}
